sites.find:
int lane_count = sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0]);
do {
    cell->Remove();
    ++cell;
    --lane_count;
} while (lane_count != 0);

replacements.text:
int lane_index = 0;
do {
    int next_lane_index = lane_index + 1;
    cell->Remove();
    ++cell;
    lane_index = next_lane_index;
} while (lane_index
         != (int)(sizeof(runtime_cells[0])
                  / sizeof(runtime_cells[0][0])));

int lane_index = 0;
do {
    cell->Remove();
    ++cell;
    ++lane_index;
} while (lane_index
         != (int)(sizeof(runtime_cells[0])
                  / sizeof(runtime_cells[0][0])));

cRSubLoc* row_end =
    cell + sizeof(runtime_cells[0]) / sizeof(runtime_cells[0][0]);
do {
    cell->Remove();
    ++cell;
} while (cell != row_end);
